Layout(content = content) { measurables, constraints ->
    val placeables = measurables.map { it.measure(constraints.copy(minWidth = 0)) }
    val width = constraints.constrainWidth(placeables.sumOf { it.width })
    val height = constraints.constrainHeight(placeables.maxOfOrNull { it.height } ?: 0)
    layout(width, height) { var x = 0; placeables.forEach { it.placeRelative(x, 0); x += it.width } }
}

